package id.nine.assistant.fit

import id.nine.assistant.core.AppLang

/**
 * Ilmu gizi dan kebugaran singkat, ditulis tangan, dengan angka dari panduan yang lazim (ISSN, WHO, Kemenkes).
 * Informasi umum untuk orang dewasa sehat, bukan nasihat medis; kondisi khusus (penyakit, hamil, di bawah 18 tahun,
 * riwayat gangguan makan) perlu ahli gizi/dokter. Kotlin murni.
 */
object NutritionKnowledge {
    class Topic(val key: String, val trigger: Regex, val id: String, val en: String)

    private fun t(key: String, pattern: String, id: String, en: String) = Topic(key, Regex("""\b(?:$pattern)\b"""), id, en)

    val topics: List<Topic> = listOf(
        t("protein_need", "apa itu protein|tentang protein|protein itu|manfaat protein|fungsi protein|waktu terbaik makan protein|kapan (?:waktu terbaik )?makan protein|protein timing|benefits? of protein|when to eat protein|kebutuhan protein|butuh protein|berapa (?:gram )?protein|protein (?:per|sehari|harian)|how much protein|protein (?:needs?|intake|requirement)",
            "Protein: orang dewasa umumnya butuh minimal 0,8 g per kg berat badan per hari. Untuk yang rutin latihan beban, panduan ISSN menyebut 1,4-2,0 g/kg sudah cukup untuk kebanyakan orang; saat defisit kalori, 1,6-2,2 g/kg membantu menjaga otot. Bagi rata ke 3-5 kali makan (sekitar 20-40 g per makan). Bila punya penyakit ginjal atau kondisi medis lain, tanyakan dokter/ahli gizi dulu.",
            "Protein: adults generally need at least 0.8 g per kg of body weight per day. For people lifting weights, the ISSN position is 1.4-2.0 g/kg for most; during a calorie deficit, 1.6-2.2 g/kg helps keep muscle. Spread it over 3-5 meals (about 20-40 g each). With kidney disease or other medical conditions, check with a doctor/dietitian first."),
        t("protein_sources", "sumber protein|makanan (?:tinggi|kaya) protein|protein (?:dari|nabati|hewani)|high protein foods?|protein sources?|source of protein|vegetarian protein|protein vegetarian",
            "Sumber protein (perkiraan): telur 1 butir ±6 g, dada ayam matang 100 g ±31 g, ikan 100 g ±22 g, tempe 100 g ±19 g, tahu putih 100 g ±8 g, Greek yoghurt 170 g ±17 g, kacang merah rebus 100 g ±9 g, whey 1 scoop ±24 g. Nabati (tempe, tahu, kacang-kacangan) bisa mencukupi bila dikombinasi dan jumlahnya cukup; vegan perlu memperhatikan vitamin B12.",
            "Protein sources (approx.): 1 egg ±6 g, cooked chicken breast 100 g ±31 g, fish 100 g ±22 g, tempeh 100 g ±19 g, plain tofu 100 g ±8 g, Greek yogurt 170 g ±17 g, boiled kidney beans 100 g ±9 g, whey 1 scoop ±24 g. Plant sources work if combined and eaten in enough quantity; vegans should watch vitamin B12."),
        t("carbs", "karbohidrat|karbo|carbs?|carbohydrates?",
            "Karbohidrat adalah bahan bakar utama latihan intens. Pilih yang berserat dan mengenyangkan (nasi merah, oat, ubi, kentang, buah) dan batasi gula tambahan. Tidak ada karbo yang \"haram\"; yang menentukan berat badan adalah total kalori. Makan karbo di sekitar waktu latihan membantu tenaga dan pemulihan.",
            "Carbohydrates are the main fuel for hard training. Favor fibrous, filling sources (brown rice, oats, sweet potato, potato, fruit) and limit added sugar. No carb is \"forbidden\"; total calories decide weight change. Carbs around training help energy and recovery."),
        t("fat", "lemak sehat|lemak jenuh|asam lemak|omega 3|omega3|healthy fats?|saturated fat|omega 3|trans fat|lemak trans|kolesterol|cholesterol",
            "Lemak penting untuk hormon dan penyerapan vitamin A, D, E, K. Utamakan lemak tak jenuh (ikan, alpukat, kacang, minyak zaitun/kanola) dan makan ikan berlemak sekitar 2 kali seminggu. WHO menyarankan lemak jenuh di bawah 10% energi dan lemak trans di bawah 1%. Lemak berenergi besar (9 kkal/g), jadi porsi tetap perlu diperhatikan.",
            "Fat supports hormones and absorption of vitamins A, D, E and K. Favor unsaturated fats (fish, avocado, nuts, olive/canola oil) and eat oily fish about twice a week. WHO suggests saturated fat under 10% of energy and trans fat under 1%. Fat is energy-dense (9 kcal/g), so portions still matter."),
        t("fiber", "serat|fiber|fibre",
            "Serat: sasaran umum sekitar 25-35 g per hari. Sumbernya sayur, buah, kacang-kacangan, oat, nasi merah, dan biji-bijian utuh. Tingkatkan pelan-pelan dan minum cukup air agar perut tidak kembung. Serat membantu kenyang lebih lama dan menjaga pencernaan.",
            "Fiber: a common target is about 25-35 g per day, from vegetables, fruit, legumes, oats, brown rice and whole grains. Increase gradually and drink enough water to avoid bloating. Fiber keeps you full longer and supports digestion."),
        t("deficit", "defisit kalori|turun berat badan|menurunkan berat badan|menurunkan lemak|cutting|diet (?:sehat|defisit)|lose weight|fat loss|calorie deficit|weight loss|bakar lemak|lemak perut|perut buncit",
            "Menurunkan lemak = defisit kalori yang moderat: sekitar 300-500 kkal di bawah kebutuhan, sehingga turun sekitar 0,25-0,5 kg per minggu (tidak lebih dari ±1% berat badan per minggu). Tetap makan protein tinggi, lanjutkan latihan beban agar otot terjaga, tidur 7-9 jam, dan jalan kaki rutin. Lemak tidak bisa dibakar di satu area saja (spot reduction itu mitos). Jangan turun di bawah batas kalori aman; Nine tidak akan menyarankan diet ekstrem.",
            "Fat loss = a moderate calorie deficit: about 300-500 kcal below needs, losing roughly 0.25-0.5 kg per week (no more than ±1% of body weight per week). Keep protein high, keep lifting to hold on to muscle, sleep 7-9 hours and walk regularly. You can't burn fat from one spot only (spot reduction is a myth). Don't go below safe calorie floors; Nine will not suggest extreme diets."),
        t("bulking", "bulking|menambah (?:berat|massa otot)|naik (?:berat|massa otot)|nambah otot|membangun otot|gain muscle|build muscle|muscle gain|bulk up|nambah berat|massa otot",
            "Menambah otot butuh tiga hal: latihan beban dengan progresi (naik beban/rep bertahap), protein cukup (sekitar 1,6-2,2 g/kg), dan surplus kalori kecil (sekitar +250-300 kkal; terlalu besar hanya menambah lemak). Latih tiap otot sekitar 2 kali seminggu dengan 10-20 set keras per minggu, tidur 7-9 jam. Pemula naik lebih cepat, lalu melambat; sabar dan konsisten.",
            "Gaining muscle takes three things: progressive resistance training (gradually more weight/reps), enough protein (about 1.6-2.2 g/kg) and a small calorie surplus (about +250-300 kcal; more just adds fat). Train each muscle about twice a week with 10-20 hard sets per week and sleep 7-9 hours. Beginners gain faster, then it slows; be patient and consistent."),
        t("preworkout", "sebelum (?:latihan|gym|olahraga|workout)|pre ?workout|makan sebelum|before (?:a )?(?:workout|training|gym)|pre ?training",
            "Sebelum latihan: makan 1-3 jam sebelumnya, utamakan karbohidrat + sedikit protein dan rendah lemak/serat agar perut nyaman (contoh: nasi + telur, roti + selai, pisang + yoghurt). Kalau latihan pagi dan tidak sempat makan, pisang kecil atau segelas susu cukup. Minum air yang cukup.",
            "Before training: eat 1-3 hours ahead, mostly carbs plus a little protein, low in fat/fiber so your stomach stays comfortable (e.g. rice + eggs, toast + jam, banana + yogurt). If you train early and have no time, a small banana or a glass of milk works. Drink enough water."),
        t("postworkout", "setelah (?:latihan|gym|olahraga|workout)|habis (?:latihan|gym|olahraga|workout)|pasca latihan|post ?workout|after (?:a )?(?:workout|training|gym)|anabolic window",
            "Setelah latihan: protein 20-40 g dan karbohidrat dalam beberapa jam sudah bagus (contoh: ayam + nasi, telur + roti, susu/whey + pisang). \"Jendela anabolik\" tidak sesempit mitosnya; total protein dan kalori harian jauh lebih menentukan daripada menit ke berapa kamu makan.",
            "After training: 20-40 g of protein plus carbs within a few hours is great (e.g. chicken + rice, eggs + toast, milk/whey + banana). The \"anabolic window\" is much wider than the myth says; total daily protein and calories matter far more than the exact minute you eat."),
        t("hydration", "minum air|berapa liter|kebutuhan air|cairan|dehidrasi|hidrasi|hydration|dehydrat\\w*|how much water|water intake|drink water",
            "Cairan: pegangan kasar sekitar 30-35 ml per kg berat badan per hari (≈2-2,5 liter untuk 70 kg), termasuk dari makanan, dan lebih banyak saat berkeringat atau cuaca panas. Urine kuning pucat tandanya cukup. Untuk latihan lebih dari 1 jam atau sangat berkeringat, tambahkan sedikit garam/elektrolit. Orang dengan penyakit jantung/ginjal perlu arahan dokter.",
            "Fluids: a rough guide is 30-35 ml per kg of body weight per day (≈2-2.5 L for 70 kg), including food, and more when sweating or in hot weather. Pale yellow urine means you're doing fine. For sessions over an hour or heavy sweating, add some salt/electrolytes. People with heart or kidney disease need medical guidance."),
        t("creatine", "kreatin|creatine",
            "Kreatin monohidrat (3-5 g per hari) adalah suplemen yang paling banyak diteliti untuk kekuatan dan massa otot, dan aman untuk orang dewasa sehat pada dosis itu. Efek samping umum: berat badan naik 1-2 kg karena air di otot. Konsultasi dulu bila ada penyakit ginjal, sedang hamil/menyusui, atau di bawah 18 tahun. Pilih produk bermerek terpercaya.",
            "Creatine monohydrate (3-5 g per day) is the most researched supplement for strength and muscle and is safe for healthy adults at that dose. Common effect: 1-2 kg weight gain from water in muscle. Check with a doctor first with kidney disease, pregnancy/breastfeeding, or under 18. Choose a trusted brand."),
        t("whey", "whey|protein shake|suplemen protein|protein powder|protein bubuk",
            "Whey adalah cara praktis menambah protein (±24 g per scoop), bukan sihir: makanan utuh sama baiknya bila targetmu tercapai. Bila perut sensitif laktosa, coba whey isolate atau protein nabati. Pilih produk yang jelas label dan izinnya.",
            "Whey is a convenient way to add protein (±24 g per scoop), not magic: whole foods work equally well if you hit your target. If lactose bothers you, try whey isolate or a plant protein. Choose products with clear labels and approvals."),
        t("caffeine", "kafein|caffeine|pre ?workout supplement|kopi sebelum",
            "Kafein sekitar 3-6 mg/kg (≈200-400 mg) 30-60 menit sebelum latihan dapat membantu performa. Batas umum untuk dewasa sehat sekitar 400 mg per hari (±4 cangkir kopi); jangan terlalu malam agar tidur tidak terganggu. Hati-hati bila hamil, tekanan darah tinggi, atau gangguan jantung.",
            "Caffeine at about 3-6 mg/kg (≈200-400 mg) 30-60 minutes before training can help performance. A common limit for healthy adults is about 400 mg per day (≈4 cups of coffee); avoid it late in the day so sleep isn't hurt. Be careful with pregnancy, high blood pressure or heart conditions."),
        t("sugar_salt", "gula tambahan|batas gula|berapa gula|berapa garam|batas garam|garam (?:per|sehari|harian)|gula (?:per|sehari|harian)|g4g1l5|added sugar|sugar limit|salt limit|how much (?:sugar|salt)|natrium|sodium|free sugars?",
            "Pedoman Kemenkes (G4-G1-L5): gula maksimal 4 sendok makan (50 g), garam 1 sendok teh (natrium 2000 mg), dan lemak 5 sendok makan (67 g) per hari. WHO juga menyarankan gula bebas di bawah 10% energi. Minuman manis (teh manis, kopi susu, boba) paling mudah membuat gula berlebih tanpa terasa.",
            "Indonesian MoH guide (G4-G1-L5): at most 4 tablespoons sugar (50 g), 1 teaspoon salt (2000 mg sodium) and 5 tablespoons fat (67 g) per day. WHO also suggests free sugars under 10% of energy. Sweet drinks (sweet tea, milk coffee, boba) are the easiest way to overshoot without noticing."),
        t("breakfast", "sarapan|breakfast",
            "Sarapan tidak wajib untuk semua orang; yang penting total makan harian cukup. Kalau kamu sarapan, protein (telur, yoghurt, tempe) + serat (oat, buah) membuat kenyang lebih lama dibanding hanya gula/roti putih.",
            "Breakfast isn't mandatory for everyone; total daily intake is what counts. If you do eat it, protein (eggs, yogurt, tempeh) plus fiber (oats, fruit) keeps you fuller than just sugar/white bread."),
        t("fasting", "puasa intermiten|intermittent fasting|puasa 16|16 8|fasting|puasa (?:untuk|buat) (?:diet|kurus)",
            "Puasa intermiten hanyalah cara mengatur jadwal makan; hasilnya tetap ditentukan total kalori dan protein. Bisa membantu sebagian orang, tetapi bukan keharusan. Tidak cocok untuk ibu hamil/menyusui, penderita diabetes yang memakai obat, di bawah 18 tahun, atau yang punya riwayat gangguan makan; konsultasi dokter dulu.",
            "Intermittent fasting is just a way to schedule meals; results still depend on total calories and protein. It helps some people but isn't required. Not suitable during pregnancy/breastfeeding, for diabetics on medication, under 18, or with a history of eating disorders; check with a doctor first."),
        t("micronutrients", "vitamin|mineral|zat besi|kalsium|vitamin d|vitamin c|vitamin b12|iron|calcium|magnesium|zinc|seng|suplemen vitamin|multivitamin",
            "Vitamin dan mineral paling baik dari makanan beragam: sayur dan buah berwarna, ikan, telur, kacang-kacangan, susu/tempe. Yang sering kurang: zat besi (terutama perempuan), kalsium, vitamin D (cukup sinar matahari pagi 10-15 menit, atau suplemen sesuai anjuran dokter), dan B12 untuk vegan. Multivitamin tidak menggantikan pola makan; dosis tinggi tanpa indikasi tidak dianjurkan.",
            "Vitamins and minerals come best from varied food: colorful vegetables and fruit, fish, eggs, legumes, dairy/tempeh. Often short: iron (especially women), calcium, vitamin D (10-15 minutes of morning sun, or a supplement as your doctor advises) and B12 for vegans. A multivitamin doesn't replace a good diet; high doses without a reason aren't recommended."),
        t("frequency", "berapa kali (?:seminggu|latihan)|frekuensi latihan|hari istirahat|rest day|how often (?:should i )?(?:train|work ?out|lift)|training frequency|split latihan|overtraining",
            "Frekuensi: melatih tiap kelompok otot sekitar 2 kali seminggu terbukti lebih baik atau sama baiknya dengan 1 kali. Untuk pemula, 3 hari seminggu full body sudah sangat efektif; beri 1-2 hari istirahat penuh. Kualitas tidur dan asupan protein menentukan pemulihan lebih dari sekadar \"cheat day\".",
            "Frequency: training each muscle group about twice a week works at least as well as once. For beginners, 3 full-body days a week is very effective; take 1-2 full rest days. Sleep quality and protein intake drive recovery more than any \"cheat day\"."),
        t("safety", "cedera|nyeri sendi|pemanasan|warm ?up|injury|form (?:yang )?benar|teknik (?:yang )?benar|sakit pinggang|sakit lutut|nyeri otot|doms",
            "Pemanasan 5-10 menit (kardio ringan + set ringan gerakan utama) mengurangi risiko cedera. Utamakan teknik yang benar sebelum menaikkan beban, naik pelan-pelan, dan istirahat cukup antar set. Pegal otot 1-3 hari setelah latihan baru (DOMS) wajar; nyeri tajam, bengkak, kesemutan, pusing, atau sesak dada bukan: hentikan latihan dan periksa ke dokter/fisioterapis.",
            "A 5-10 minute warm-up (light cardio + light sets of your main lift) lowers injury risk. Learn good technique before adding weight, progress slowly and rest enough between sets. Muscle soreness 1-3 days after new training (DOMS) is normal; sharp pain, swelling, tingling, dizziness or chest tightness is not: stop and see a doctor/physiotherapist."),
        t("bmi", "apa itu bmi|apa itu imt|\\bimt\\b|body mass index|indeks massa tubuh|bmi itu",
            "IMT/BMI = berat (kg) dibagi tinggi (m) kuadrat. Patokan Asia-Pasifik: 18,5-22,9 normal, 23-24,9 berat badan lebih, ≥25 obesitas. BMI tidak membedakan otot dan lemak, jadi orang berotot bisa tinggi tanpa kelebihan lemak; persentase lemak tubuh (mis. dari InBody) dan lingkar perut melengkapi gambarannya.",
            "BMI = weight (kg) divided by height (m) squared. Asia-Pacific guide: 18.5-22.9 normal, 23-24.9 overweight, ≥25 obese. BMI can't tell muscle from fat, so muscular people can score high without excess fat; body-fat percentage (e.g. from InBody) and waist circumference complete the picture."),
        t("inbody_explain", "apa itu inbody|cara membaca inbody|arti (?:angka )?inbody|what is inbody|how to read inbody|inbody itu",
            "InBody memperkirakan komposisi tubuh lewat arus listrik sangat kecil (BIA). Angka utama: Skeletal Muscle Mass (otot rangka), Body Fat Mass dan Percent Body Fat/PBF (lemak), Visceral Fat Level (lemak perut dalam; 1-9 normal), BMR (kalori istirahat), dan InBody Score. Hasil dipengaruhi air tubuh, jadi ukur di kondisi yang mirip (pagi, setelah buang air, belum makan/latihan berat, tanpa minum banyak) dan lihat TREN beberapa kali ukur, bukan satu angka. Ini bukan diagnosis medis. Kirim fotonya dan saya bantu bacakan.",
            "InBody estimates body composition with a tiny electrical current (BIA). Key numbers: Skeletal Muscle Mass, Body Fat Mass and Percent Body Fat/PBF, Visceral Fat Level (1-9 is normal), BMR (resting calories) and the InBody Score. Results are affected by body water, so measure under similar conditions (morning, after the toilet, not right after eating or hard training, no heavy drinking) and watch the TREND over several scans, not one number. It's not a medical diagnosis. Send a photo and I'll help read it."),
        t("myths", "mitos|myth|detoks|detox|karbo malam|makan malam bikin gemuk|spot reduction|makan malam gemuk|jus detoks|teh pelangsing|pelangsing",
            "Mitos umum: lemak di satu area bisa dibakar dengan latihan area itu (tidak); makan malam otomatis bikin gemuk (yang penting total kalori); detoks, teh pelangsing, atau diet kilat memberi hasil permanen (yang turun biasanya air dan hasilnya kembali); \"cuci lemak\" lewat keringat banyak (keringat hanya air). Yang terbukti: defisit kalori moderat, protein cukup, latihan beban, tidur, dan konsisten.",
            "Common myths: you can burn fat from one area by training it (no); eating at night automatically makes you fat (total calories matter); detoxes, slimming teas or crash diets give lasting results (mostly water, and it returns); sweating \"melts fat\" (sweat is water). What works: a moderate deficit, enough protein, resistance training, sleep and consistency."),
        t("snacks", "camilan sehat|snack sehat|healthy snacks?|ngemil apa|cemilan sehat|camilan tinggi protein",
            "Camilan yang mengenyangkan: telur rebus, yoghurt plain/Greek + buah, tempe atau tahu panggang, kacang rebus/panggang segenggam, edamame, pisang + selai kacang, susu. Pilih yang protein atau seratnya tinggi; gorengan, biskuit, dan minuman manis cepat menambah kalori tanpa membuat kenyang lama.",
            "Filling snacks: boiled eggs, plain/Greek yogurt + fruit, baked tempeh or tofu, a handful of nuts/boiled beans, edamame, banana + peanut butter, milk. Pick ones high in protein or fiber; fried snacks, biscuits and sweet drinks add calories fast without keeping you full."),
        t("sleep_recovery", "tidur (?:untuk|dan|buat) (?:otot|pemulihan|latihan|gym)|pemulihan otot|berapa jam tidur|muscle recovery|sleep (?:and|for) (?:muscle|recovery|training|gym)|how (?:much|many hours) sleep|recovery",
            "Tidur 7-9 jam penting untuk pemulihan otot, nafsu makan, dan tenaga latihan. Kurang tidur membuat lapar dan ngidam makanan manis lebih sering dan performa turun. Jadwal tidur yang konsisten dan layar dijauhkan sebelum tidur membantu.",
            "Sleeping 7-9 hours matters for muscle recovery, appetite control and training energy. Short sleep raises hunger and sweet cravings and lowers performance. A consistent schedule and no screens before bed help."),
        t("eating_out", "makan di luar|warung|nasi padang|restoran|fast food|makan di restoran|eating out",
            "Makan di luar: pilih lauk panggang/rebus/kukus dibanding goreng, minta nasi setengah porsi bila perlu, tambah sayur, hati-hati kuah santan, sambal minyak, dan minuman manis. Porsi di warung sering lebih besar dari perkiraan; catat dengan angka kalori langsung bila tahu (mis. \"makan nasi padang 700 kalori\").",
            "Eating out: choose grilled/boiled/steamed dishes over fried, ask for half rice if needed, add vegetables, and watch coconut-milk gravies, oily sambal and sweet drinks. Restaurant portions are often bigger than you think; log with a direct calorie number when you know it (e.g. \"ate nasi padang 700 calories\").")
    )

    /** Topik yang paling cocok untuk teks ternormalisasi, atau null. */
    fun match(norm: String): Topic? = topics.firstOrNull { it.trigger.containsMatchIn(norm) }

    fun answer(topic: Topic, lang: AppLang): String = lang.t(topic.id, topic.en) +
        lang.t("\n\n(Informasi umum, bukan nasihat medis.)", "\n\n(General information, not medical advice.)")
}
